# =============================================================================
# StmCorpusBuild.R
# Build the corpus for STM for LLM-generated explanations
# Requires objects from grade_mc_responses.R and readDOCX-AllModels.R
# =============================================================================

library(dplyr)
library(stringr)
library(readr)
library(stm)
library(tidytext)
library(tidyr)

# -----------------------------------------------------------------------------
# 1. scored_responses_long.csv generated by grade_mc_responses.R
# -----------------------------------------------------------------------------

scored_long <- read_csv("scored_responses_long.csv")

# -----------------------------------------------------------------------------
# 2. Load explanation text
# -----------------------------------------------------------------------------
# all_explanations_long.csv generated with readDOCX-AllModels.R
# Must contain: Question, Exam, Model, explanation_text

explanations_long <- read_csv("all_explanations_long.csv")

# -----------------------------------------------------------------------------
# 3. Create Model crosswalk because model names differ between 
# scored_long and explanations_long
# -----------------------------------------------------------------------------

model_crosswalk <- tibble::tribble(
  ~model_folder,                    ~Model_accuracy,
  "claude-3-7-sonnet",              "Claude37",
  "claude-sonnet-4",                "Claude4",
  "claude-sonnet-4-6",              "Claude46",
  "gemini-2.0-flash-lite",          "Gemini20",
  "gemini-2.5-flash-lite",          "Gemini25",
  "gemini-3.1-flash-lite-preview",  "Gemini31",
  "gpt-4o",                         "GPT4o",
  "gpt-5",                          "GPT5",
  "gpt-5-4",                        "GPT54",
  "gpt-5.1",                        "GPT51",
  "gpt-5.4-mini",                   "GPT54-mini",
  "gpt-5.4-nano",                   "GPT54-nano",
  "grok-2-vision",                  "Grok2-vision",
  "grok-4-1",                       "Grok41",
  "grok-4.3",                       "Grok43"
)
# -----------------------------------------------------------------------------
# 3. Merge explanations with accuracy metadata
# -----------------------------------------------------------------------------

stm_meta <- all_explanations %>%
  left_join(model_crosswalk, by = "model_folder") %>%
  left_join(
    scored_long %>%
      mutate(
        Question = as.numeric(Question),
        Exam = as.character(Exam),
        Model_accuracy = as.character(Model)
      ) %>%
      select(
        Question,
        Exam,
        Model_accuracy,
        Truth,
        Response,
        Response_clean,
        Score
      ),
    by = c("Question", "Exam", "Model_accuracy")
  ) %>%
  mutate(
    Model = factor(model_folder),
    Exam = factor(Exam, levels = c("ACTM", "AP", "CAOS", "GE")),
    qtype = factor(qtype, levels = c("MC", "SA")),
    image = factor(image, levels = c("No image", "Image")),
    correct = case_when(
      qtype == "SA" ~ "Not scored",
      Exam == "AP" ~ "Not scored",
      Score == 1 ~ "Correct",
      Score == 0 ~ "Incorrect",
      TRUE ~ "Not scored"
    ),
    correct = factor(correct, levels = c("Incorrect", "Correct", "Not scored"))
  )

# Create three types of "not scored" questions
stm_meta <- stm_meta %>%
  mutate(
    MC_Response_Type = case_when(
      qtype == "MC" & Response_clean == "NC" ~ "No conclusion",
      qtype == "MC" & Response_clean == "NA_RESP" ~ "No response",
      qtype == "MC" & Score == 1 ~ "Correct",
      qtype == "MC" & Score == 0 ~ "Incorrect",
      TRUE ~ NA_character_
    ),
    MC_Response_Type = factor(
      MC_Response_Type,
      levels = c(
        "Correct",
        "Incorrect",
        "No conclusion",
        "No response"
      )
    )
  )
# -----------------------------------------------------------------------------
# 4. Sanity Checks
# -----------------------------------------------------------------------------

stm_meta %>%
  count(qtype, MC_Response_Type)

stm_meta %>%
  filter(qtype == "MC") %>%
  count(MC_Response_Type)

stm_meta %>%
  filter(qtype == "MC") %>%
  count(Model_accuracy, MC_Response_Type) %>%
  group_by(Model_accuracy) %>%
  mutate(percent = round(100 * n / sum(n), 1)) %>%
  ungroup()

# -----------------------------------------------------------------------------
# 5. Compute response summary
# -----------------------------------------------------------------------------

response_summary <- stm_meta %>%
  filter(qtype == "MC") %>%
  count(Model_accuracy, MC_Response_Type) %>%
  group_by(Model_accuracy) %>%
  mutate(
    Percent = round(100 * n / sum(n), 1)
  ) %>%
  tidyr::pivot_wider(
    names_from = MC_Response_Type,
    values_from = c(n, Percent),
    values_fill = 0
  ) %>%
  ungroup()

## Nice tables from response_summary
library(knitr)
library(kableExtra)

response_table <- response_summary %>%
  transmute(
    Model = Model_accuracy,
    `Correct (%)` = Percent_Correct,
    `Incorrect (%)` = Percent_Incorrect,
    `No conclusion (%)` = `Percent_No conclusion`,
    `No response (%)` = `Percent_No response`
  ) %>%
  arrange(desc(`Correct (%)`))

# Percentages only
response_table %>%
  kable(
    format = "latex",
    booktabs = TRUE,
    digits = 1,
    caption = "Multiple-choice response behavior by model.",
    label = "tab:response_behavior"
  ) %>%
  kable_styling(latex_options = c("hold_position"))

# Counts and percentages
response_table_counts <- response_summary %>%
  transmute(
    Model = Model_accuracy,
    Correct = paste0(n_Correct, " (", Percent_Correct, "\\%)"),
    Incorrect = paste0(n_Incorrect, " (", Percent_Incorrect, "\\%)"),
    `No conclusion` = paste0(`n_No conclusion`, " (", `Percent_No conclusion`, "\\%)"),
    `No response` = paste0(`n_No response`, " (", `Percent_No response`, "\\%)")
  ) %>%
  arrange(desc(parse_number(Correct)))

# =============================================================================
# 5. Clean explanation text before STM
# =============================================================================
clean_explanation_text <- function(x) {
  x %>%
    # normalize line endings
    str_replace_all("\r\n|\r", "\n") %>%
    
    # remove markdown headings
    str_replace_all("(?m)^#+\\s*", " ") %>%
    
    # remove common boilerplate headings
    str_replace_all("(?i)multiple choice question response", " ") %>%
    str_replace_all("(?i)short answer question response", " ") %>%
    str_replace_all("(?i)final answer", " ") %>%
    str_replace_all("(?i)answer:", " ") %>%
    str_replace_all("(?i)explanation:", " ") %>%
    str_replace_all("(?i)reasoning:", " ") %>%
    str_replace_all("(?i)solution:", " ") %>%
    
    # remove common LLM filler phrases
    str_replace_all("(?i)let'?s solve this step by step", " ") %>%
    str_replace_all("(?i)let me work through this", " ") %>%
    str_replace_all("(?i)we need to determine", " ") %>%
    str_replace_all("(?i)the correct answer is", " ") %>%
    str_replace_all("(?i)therefore,? the answer is", " ") %>%
    str_replace_all("(?i)thus,? the answer is", " ") %>%
    
    # remove isolated answer-choice declarations
    str_replace_all("(?i)\\boption\\s+[a-e]\\b", " ") %>%
    str_replace_all("(?i)\\bchoice\\s+[a-e]\\b", " ") %>%
    str_replace_all("(?i)\\banswer\\s+[a-e]\\b", " ") %>%
    
    # remove markdown bullets and numbering artifacts
    str_replace_all("(?m)^\\s*[-*+]\\s+", " ") %>%
    str_replace_all("(?m)^\\s*\\d+\\.\\s+", " ") %>%
    
    # remove markdown emphasis/backticks
    str_replace_all("[`*_]", " ") %>%
    
    # remove URLs, if any
    str_replace_all("https?://\\S+|www\\.\\S+", " ") %>%
    
    # normalize whitespace
    str_replace_all("\\s+", " ") %>%
    str_squish()
}

stm_meta <- stm_meta %>%
  mutate(
    explanation_clean = clean_explanation_text(explanation_text),
    n_words_raw = str_count(explanation_text, "\\S+"),
    n_words_clean = str_count(explanation_clean, "\\S+")
  )

# Check that the cleaning did not remove too much.
stm_meta %>%
  summarise(
    n_docs = n(),
    n_empty_clean = sum(explanation_clean == "" | is.na(explanation_clean)),
    mean_words_raw = mean(n_words_raw),
    mean_words_clean = mean(n_words_clean),
    median_words_raw = median(n_words_raw),
    median_words_clean = median(n_words_clean)
  )

# Inspect a few examples
stm_meta %>%
  select(Model, Exam, Question, qtype, explanation_text, explanation_clean) %>%
  slice_sample(n = 5)

# Frequent word check
top_words <- stm_meta %>%
  select(doc_id = file_name, explanation_clean) %>%
  unnest_tokens(word, explanation_clean) %>%
  count(word, sort = TRUE)

top_words %>%
  print(n = 50)

## Remove some more artifacts
stm_meta <- stm_meta %>%
  mutate(
    explanation_clean = explanation_clean %>%
      str_replace_all("[“”‘’]", "'") %>%
      str_replace_all("\\b\\w*'ll\\b", " ") %>%
      str_replace_all("\\b\\w*n't\\b", " not ") %>%
      str_replace_all("(?<=\\s)-(?=\\w)", " ") %>%
      str_replace_all("\\s+", " ") %>%
      str_squish()
  )


