thoughts20 <- findThoughts(
  stm20,
  texts = meta$explanation_clean,
  n = 3
)

# -----------------------------------------------------------------------------
# 3. Convert representative documents into a tidy table
# -----------------------------------------------------------------------------

representative_docs20 <- map_dfr(
  1:K_final,
  function(k) {
    
    docs_k <- thoughts20$docs[[k]]
    
    tibble(
      Topic = k,
      Representative_Doc = seq_along(docs_k),
      Text = docs_k
    )
  }
)

representative_docs20 <- representative_docs20 %>%
  mutate(
    Text_short = str_trunc(Text, width = 500)
  )

print(representative_docs20, n = 60)

# -----------------------------------------------------------------------------
# 4. Helper function to inspect a single topic
# -----------------------------------------------------------------------------

inspect_topic <- function(topic_num, n_chars = 1000) {
  
  cat("\n============================================================\n")
  cat("Topic", topic_num, "\n")
  cat("============================================================\n\n")
  
  cat("Highest probability words:\n")
  cat(topic_word_table$Highest_Prob[topic_num], "\n\n")
  
  cat("FREX words:\n")
  cat(topic_word_table$FREX[topic_num], "\n\n")
  
  cat("Representative documents:\n\n")
  
  representative_docs20 %>%
    filter(Topic == topic_num) %>%
    mutate(Text_display = str_trunc(Text, n_chars)) %>%
    pull(Text_display) %>%
    walk2(
      seq_along(.),
      ~ cat("Document", .y, ":\n", .x, "\n\n")
    )
}

inspect_topic(1)
inspect_topic(15)
inspect_topic(20)

