  group_by(Exam, Question) %>%
  summarise(
    across(starts_with("Topic_"), mean),
    .groups = "drop"
  )

# Find which topic is most associated with each question
question_topics <- topic_question %>%
  group_by(Exam, Question) %>%
  summarise(
    across(starts_with("Topic_"), mean),
    .groups = "drop"
  ) %>%
  rowwise() %>%
  mutate(
    DominantTopic = which.max(c_across(starts_with("Topic_"))),
    DominantLabel = topic_labels[DominantTopic],
    DominantProb = max(c_across(starts_with("Topic_")))
  ) %>%
  ungroup()

# For each topic, which questions have an average topic 
# probability greater than 0.20?

# Create long format
question_topics_long <- question_topics %>%
  select(Exam, Question, starts_with("Topic_")) %>%
  pivot_longer(
    cols = starts_with("Topic_"),
    names_to = "Topic",
    values_to = "Mean_Probability"
  ) %>%
  mutate(
    Topic = as.integer(gsub("Topic_", "", Topic)),
    Topic_Label = topic_labels[Topic]
  )

# threshold questions 
topic_questions_25 <- question_topics_long %>%
